import { useEffect, useRef } from 'react';
import { Link, Navigate, useLocation } from 'react-router-dom';
import { FREEZE_EVERY, MAX_FREEZES, PRO_MODES, SPEED_SECONDS, type ModeId } from '@lexpad/core';
import { BoxesDiagram } from '@/components/ui/BoxesDiagram.js';
import { Icon } from '@/components/ui/Icon.js';
import { getActiveNotebook } from '@/db/repo.js';
import { getMeta } from '@/db/schema.js';
import { t, type MessageKey } from '@/i18n/index.js';
import { useLiveQuery } from '@/lib/useLiveQuery.js';
import { proHere, useBilling } from '@/features/billing/state.js';
import { shownModes } from '@/features/modes/data.js';
import { loadSrsView, shows, type SrsView } from '@/features/schedule/data.js';
import { HOW_FOCUS, SETTINGS_ROOT, settingsPath } from '@/features/settings/paths.js';
import { SubPage } from '@/features/settings/SettingsKit.js';
import { learnShows } from './state.js';
import styles from './How.module.css';

/** What the page reads, all of it local. */
interface HowData {
  ready: boolean;
  srs: SrsView | undefined;
  /** The default number of miss-days before Lexpad asks about a word, from the server. */
  leechDefault: number | undefined;
  targetLang: string | undefined;
  meaningLang: string | undefined;
}

const LOADING: HowData = {
  ready: false,
  srs: undefined,
  leechDefault: undefined,
  targetLang: undefined,
  meaningLang: undefined,
};

async function loadHow(): Promise<HowData> {
  const [srs, stored, notebook] = await Promise.all([loadSrsView(), getMeta('srs'), getActiveNotebook()]);
  return {
    ready: true,
    srs,
    leechDefault: stored?.state?.defaults.leechThreshold,
    targetLang: notebook?.targetLang,
    meaningLang: notebook?.meaningLang,
  };
}

const MODE_LINES: Record<ModeId, MessageKey> = {
  match: 'how.modeMatch',
  speed: 'how.modeSpeed',
  dictation: 'how.modeDictation',
  builder: 'how.modeBuilder',
  collocation: 'how.modeCollocation',
  sayIt: 'how.modeSayIt',
  sentence: 'how.modeSentence',
};

/**
 * How Lexpad works (the new learner's journey, §4): five short cards on one
 * page, and the options folded underneath. The one place the whole idea is
 * written down, for whoever goes looking: Help & about, the first session
 * summaries and the schedule page link here, and it never opens by itself.
 *
 * It describes only what this account has: an option switched off for it is
 * not explained, and "Part of Pro" follows the same silences as `ProOffer` —
 * nothing until the plan is known, never for a paid account or a notebook
 * Lexpad never charges for. It reads the plan only if another screen already
 * has; this page sends no request.
 */
export function How(): React.JSX.Element {
  const data = useLiveQuery(async () => loadHow(), LOADING, []);
  const billing = useBilling((state) => state.state);
  const { hash } = useLocation();
  const landed = useRef(false);

  // Opened at a card ("How it works" on a summary opens at the boxes): bring
  // it into view once it is drawn, once a visit.
  useEffect(() => {
    if (!data.ready || landed.current || hash === '') return;
    const target = document.getElementById(hash.slice(1));
    if (target === null) return;
    landed.current = true;
    target.scrollIntoView({ block: 'start' });
  }, [data.ready, hash]);

  if (!data.ready || data.srs === undefined) {
    return (
      <SubPage title={t('how.title')}>
        <span className="sr-only" role="status">
          {t('state.loading')}
        </span>
      </SubPage>
    );
  }
  const srs = data.srs;
  // An address only the new learner's journey links to: without it, Settings.
  if (!learnShows(srs)) return <Navigate to={SETTINGS_ROOT} replace />;

  const modes = shownModes(srs);
  const proMark = (mode: ModeId): boolean =>
    PRO_MODES.has(mode) && billing !== null && !proHere(billing, data.targetLang, data.meaningLang);
  const smart = shows(srs, 'smart');

  const more: { id: string; title: MessageKey; body: React.ReactNode }[] = [
    ...(smart
      ? [{ id: 'boxes-smart', title: 'how.boxesVsSmartTitle' as const, body: t('how.boxesVsSmart') }]
      : []),
    ...(smart
      ? [
          {
            id: 'target',
            title: 'how.targetTitle' as const,
            body: t('how.target', {
              relaxed: srs.choices.retention.relaxed,
              balanced: srs.choices.retention.balanced,
              exam: srs.choices.retention.exam,
            }),
          },
        ]
      : []),
    ...(shows(srs, 'afterMiss')
      ? [{ id: 'after-miss', title: 'how.afterMissTitle' as const, body: t('how.afterMiss') }]
      : []),
    ...(shows(srs, 'practiceOnly')
      ? [{ id: 'extra-practice', title: 'how.extraPracticeTitle' as const, body: t('how.extraPractice') }]
      : []),
    ...(shows(srs, 'reviewCap')
      ? [{ id: 'limits', title: 'how.limitsTitle' as const, body: t('how.limits') }]
      : []),
    ...(shows(srs, 'leech') && data.leechDefault !== undefined && data.leechDefault > 0
      ? [
          {
            id: 'leech',
            title: 'how.leechTitle' as const,
            body: t('how.leech', { count: data.leechDefault }),
          },
        ]
      : []),
    ...(smart && shows(srs, 'tuning')
      ? [{ id: 'tuning', title: 'how.tuningTitle' as const, body: t('how.tuning') }]
      : []),
    ...(shows(srs, 'trueRetention')
      ? [{ id: 'retention', title: 'how.retentionTitle' as const, body: t('how.retention') }]
      : []),
    ...(modes.length > 0
      ? [
          {
            id: 'modes',
            title: 'how.modesTitle' as const,
            body: (
              <ul className={styles.modes}>
                {modes.map((mode) => (
                  <li key={mode}>
                    {t(MODE_LINES[mode], { seconds: SPEED_SECONDS })}
                    {proMark(mode) && <> {t('how.partOfPro')}</>}
                  </li>
                ))}
              </ul>
            ),
          },
        ]
      : []),
    ...(shows(srs, 'streakFreeze')
      ? [
          {
            id: 'freeze',
            title: 'how.freezeTitle' as const,
            body: t('how.freeze', { days: FREEZE_EVERY, max: MAX_FREEZES }),
          },
        ]
      : []),
  ];

  const cards: { id: string; title: MessageKey; body: string; extra?: React.ReactNode }[] = [
    { id: 'words', title: 'how.wordsTitle', body: t('how.wordsBody') },
    { id: 'check', title: 'how.checkTitle', body: t('how.checkBody') },
    {
      id: HOW_FOCUS.boxes,
      title: 'how.boxesTitle',
      body: t('how.boxesBody'),
      extra: <BoxesDiagram className={styles.diagram} />,
    },
    {
      id: 'due',
      title: 'how.dueTitle',
      body: modes.length > 0 ? t('how.dueBody') : t('how.dueBodyNoGames'),
    },
    {
      id: 'change',
      title: 'how.changeTitle',
      body: t('how.changeBody'),
      extra: (
        <div className={styles.links}>
          <Link to={settingsPath('schedule')} className={styles.link}>
            {t('how.changeSchedule')}
            <Icon name="chevronRight" size={14} weight={2.2} className={styles.go} />
          </Link>
          <Link to={settingsPath('practice')} className={styles.link}>
            {t('how.changePractice')}
            <Icon name="chevronRight" size={14} weight={2.2} className={styles.go} />
          </Link>
        </div>
      ),
    },
  ];

  return (
    <SubPage title={t('how.title')}>
      <ol className={styles.cards}>
        {cards.map((card, index) => (
          <li key={card.id} id={card.id} className={styles.card}>
            <span className={styles.number} aria-hidden="true">
              {index + 1}
            </span>
            <div className={styles.body}>
              <h2 id={`how-${card.id}`} className={styles.cardTitle}>
                {t(card.title)}
              </h2>
              <p className={styles.text}>{card.body}</p>
              {card.extra}
            </div>
          </li>
        ))}
      </ol>

      {more.length > 0 && (
        <section className={styles.more} aria-labelledby="how-more">
          <h2 id="how-more" className={styles.moreTitle}>
            {t('how.moreTitle')}
          </h2>
          <div className={styles.folds}>
            {more.map((item) => (
              <details key={item.id} id={`how-${item.id}`} className={styles.fold}>
                <summary className={styles.summary}>
                  <span>{t(item.title)}</span>
                  <Icon name="chevronDown" size={16} weight={2.2} className={styles.chevron} />
                </summary>
                <div className={styles.answer}>{item.body}</div>
              </details>
            ))}
          </div>
        </section>
      )}
    </SubPage>
  );
}
